function Scoring:GetProfileDescription()
    local context = APR:GetRewardBuildContext()
    local label = context.label or context.className or "APR"
    if not self:GetDefaultScale() then return label .. ": " .. (UNAVAILABLE or UNKNOWN or "?") end
    return label
end--[[APR_DIAG]]; Scoring.GetProfileDescription = APRTrace("APR-Core/features/questing/RewardScoring.lua:59:Scoring:GetProfileDescription#5", Scoring.GetProfileDescription)--[[/APR_DIAG]]

local function aliasValue(stats, keys)
    local value = 0
    for _, key in ipairs(keys) do
        local candidate = stats[key]
        if not accessible(candidate) then return nil end
        if candidate ~= nil then
            if not number(candidate) then return nil end
            value = math.max(value, candidate)
        end
    end
    return value
end--[[APR_DIAG]]; aliasValue = APRTrace("APR-Core/features/questing/RewardScoring.lua:66:aliasValue#6", aliasValue)--[[/APR_DIAG]]

local function defaultScore(link, scale, slot)
    local getStats = itemAPI("GetItemStats")
    if not getStats then return nil, false end
    local ok, stats = --[[APR_DIAG]]APRPCall--[=[--[[/APR_DIAG]]pcall--[[APR_DIAG]]]=]--[[/APR_DIAG]](getStats, link)
    if not ok or not accessible(stats) or type(stats) ~= "table" or (canaccesstable and not canaccesstable(stats)) then
        return nil, false
    end
    if scale.emptyArmorOnly then
        for _, value in pairs(stats) do
            if not number(value) then return nil, false end
            if value < 0 then return 0, true end
        end
    end
    local attributes = {}
    for stat, keys in pairs(attributeAliases) do
        attributes[stat] = aliasValue(stats, keys)
        if attributes[stat] == nil then return nil, false end
    end
    for _, hybrid in ipairs(hybrids) do
        local value = stats[hybrid[1]]
        if not accessible(value) then return nil, false end
        if value ~= nil then
            if not number(value) then return nil, false end
            local best = scale.primaryStat
            local supported = false
            for i = 2, #hybrid do
                if hybrid[i] == best then supported = true end
            end
            if not supported then best = hybrid[2] end
            for i = 2, #hybrid do
                if (scale.weights[hybrid[i]] or 0) > (scale.weights[best] or 0) then best = hybrid[i] end
            end
            attributes[best] = math.max(attributes[best], value)
        end
    end
    local total = 0
    for stat, value in pairs(attributes) do
        total = total + value * (scale.weights[stat] or 0)
    end
    for stat, keys in pairs(aliases) do
        local value = aliasValue(stats, keys)
        if value == nil then return nil, false end
        -- The baseline models white weapon damage, not special attacks/talents.
        -- Attributes remain fully active in either hand; only offhand DPS is halved.
        local contribution = stat == "WeaponDPS" and slot == 17 and 0.5 or 1
        total = total + value * (scale.weights[stat] or 0) * contribution
    end
    return total, number(total)
end--[[APR_DIAG]]; defaultScore = APRTrace("APR-Core/features/questing/RewardScoring.lua:79:defaultScore#7", defaultScore)--[[/APR_DIAG]]

